import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"開啟本地服務（LM Studio）","description":"LM Studio Local Server：監聽地址、端口與 CORS，供手機 MiniTavern 經局域網 BYOK 連接。","frontmatter":{"title":"開啟本地服務（LM Studio）","description":"LM Studio Local Server：監聽地址、端口與 CORS，供手機 MiniTavern 經局域網 BYOK 連接。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"開啟本地服務（LM Studio） · MiniTavern Docs"}],["meta",{"property":"og:description","content":"LM Studio Local Server：監聽地址、端口與 CORS，供手機 MiniTavern 經局域網 BYOK 連接。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/lmstudio/server"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/lmstudio/server"}]]},"headers":[],"relativePath":"zh-TW/lmstudio/server.md","filePath":"zh-TW/lmstudio/server.md","lastUpdated":1787224147000}'),o={name:"zh-TW/lmstudio/server.md"};function l(d,t,n,s,c,h){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="開啟本地服務-lm-studio" tabindex="-1">開啟本地服務（LM Studio） <a class="header-anchor" href="#開啟本地服務-lm-studio" aria-label="Permalink to &quot;開啟本地服務（LM Studio）&quot;">​</a></h1><h2 id="打開-local-server" tabindex="-1">打開 Local Server <a class="header-anchor" href="#打開-local-server" aria-label="Permalink to &quot;打開 Local Server&quot;">​</a></h2><ol><li>在 LM Studio 中打開 <strong>Local Server</strong>（或 Developer / 服務器）面板。</li><li>確認已加載要對外提供的模型。</li><li>開啟服務器；記下界面上的：</li></ol><table tabindex="0"><thead><tr><th>項</th><th>常見默認</th></tr></thead><tbody><tr><td>端口</td><td><code>1234</code>（以你界面顯示為準）</td></tr><tr><td>監聽地址</td><td>需允許局域網（若有 <code>0.0.0.0</code> / 「允許網絡中的設備訪問」之類開關，請打開）</td></tr></tbody></table><ol start="4"><li>本機可先測：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:1234/v1/models</span></span></code></pre></div><p>瀏覽器或 <code>curl</code> 能看到模型列表即服務正常。</p><h2 id="局域網與防火牆" tabindex="-1">局域網與防火牆 <a class="header-anchor" href="#局域網與防火牆" aria-label="Permalink to &quot;局域網與防火牆&quot;">​</a></h2><ul><li>查電腦局域網 IP（見 <a href="./../quickstart#step-4查電腦局域網-ip">快速開始</a>）。</li><li>防火牆放行 LM Studio 使用的 TCP 端口（常見 <code>1234</code>）。</li><li>用另一臺設備訪問 <code>http://YOUR_PC_IP:1234/v1/models</code> 驗證。</li></ul><h2 id="給-minitavern-用的地址" tabindex="-1">給 MiniTavern 用的地址 <a class="header-anchor" href="#給-minitavern-用的地址" aria-label="Permalink to &quot;給 MiniTavern 用的地址&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:1234/v1</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>填寫</th></tr></thead><tbody><tr><td>Base URL</td><td>上一行地址</td></tr><tr><td>API Key</td><td>通常可留空或任意佔位</td></tr><tr><td>模型名</td><td>與 Local Server 當前加載 / 列表中的 <strong>id</strong> 一致</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./../connect-app/minitavern">在 MiniTavern 中配置</a></p>',14)])])}const v=e(o,[["render",l]]);export{u as __pageData,v as default};
